/**
 * The HED-SCORE term index as generated by `tools/hed-score/generate_index.py`: the SCORE terms of one schema release
 * and the artifact subtree of its partnered HED standard, the units their value placeholders accept, and the release's
 * identity.
 */
export type HedScoreIndex = {
    /** CC-BY-4.0 attribution of the schema the index derives from; shown wherever the terms are. */
    attribution: string
    /** Roots of the index: the top-level SCORE branches in schema order, then the subtrees of `standardSubtrees`. */
    branches: string[]
    /** Layout version of the index file. */
    format: number
    /** SPDX identifier of the schema's licence. */
    license: string
    /** The release the index was generated from. */
    schema: HedScoreSchema
    /**
     * Roots taken from the HED standard rather than the SCORE library, each mapped to the standard's top-level branch
     * it sits under. That branch is what a server restricting branches checks the subtree's terms against.
     */
    standardSubtrees: Record<string, string>
    /** Every SCORE node in schema order, parents before children. */
    terms: HedScoreTerm[]
    /** Unit strings per unit class named by a term, SI prefixes applied. */
    units: Record<string, HedScoreUnitClass>
}

/** The schema release an index was generated from. */
export type HedScoreSchema = {
    /** HED library name, always `score`. */
    library: string
    /** SHA-256 of the merged schema XML the index was generated from. */
    sha256: string
    /** Library release version. */
    version: string
    /** Version of the HED standard the library is partnered with. */
    withStandard: string
}

/** One SCORE node. */
export type HedScoreTerm = {
    /** Deprecated in this release; kept so a stored code still resolves, never offered. */
    deprecated?: boolean
    /** The schema's description, whitespace normalised. */
    description: string
    /** Persistent HED identifier (`HED_<number>`). */
    hedId: string
    /** Short-form tag, unique across the merged schema. */
    name: string
    /** Short form of the parent node, `null` for a top-level branch. */
    parent: string | null
    /** The tag is only valid with a child or a value. */
    requireChild?: boolean
    /** Unit classes of the value placeholder. */
    unitClasses?: string[]
    /** Value classes of the value placeholder; present only when the term takes a value (`Tag/<value>`). */
    valueClasses?: string[]
}

/** A loaded index with lookups over its terms. */
export interface HedScoreTermIndex extends HedScoreIndex {
    /**
     * The top-level branch a term sits under, or `null` for an unknown name.
     * @param name - Short-form tag.
     */
    branchOf (name: string): string | null
    /**
     * The term with the given short form, or `null`.
     * @param name - Short-form tag.
     */
    getTerm (name: string): HedScoreTerm | null
    /**
     * The top-level branch of the merged schema a term sits under, which is the name a branch policy uses, or `null`
     * for an unknown name. It differs from {@link branchOf} only for the subtrees of `standardSubtrees`.
     * @param name - Short-form tag.
     */
    schemaBranchOf (name: string): string | null
}

/**
 * A HED code's `meta` as the platform's validator requires it: the release the string was written against, so a stored
 * code can be re-validated later.
 */
export type HedSchemaMeta = {
    schema: {
        library: string
        version: string
        with_standard: string
    }
}

/** The units a unit class accepts, and the one a value is written in when none is chosen. */
export type HedScoreUnitClass = {
    /** The schema's default unit for the class. */
    default: string | null
    /** Every accepted unit string, sorted. */
    units: string[]
}
